import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.Bx7X8BVG.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"CF Tunnel Manager","text":"Cloudflare Tunnel 多隧道管理面板","tagline":"单容器内多条隧道同时在线 · Docker 一键部署 · 内置国内网络加速","image":{"src":"/logo.svg","alt":"CF Tunnel Manager"},"actions":[{"theme":"brand","text":"快速开始","link":"/guide/"},{"theme":"alt","text":"获取 Cloudflare 凭据","link":"/get-credentials"},{"theme":"alt","text":"GitHub","link":"https://github.com/lieren2012/cloudflare-tunnel-manager"}]},"features":[{"icon":"🚇","title":"多隧道并行","details":"每条隧道独立进程，可同时在线、独立启停，异常退出按指数退避自动重连（1s → 60s）。原版同时只能连 1 条。"},{"icon":"🎲","title":"一键随机域名","details":"设定默认域名后，点一下就能生成随机二级域名，并自动在 Cloudflare 创建 DNS CNAME，橙云代理自带 HTTPS。"},{"icon":"👥","title":"多用户与数据隔离","details":"首个注册者自动成为管理员，后续注册需管理员审核；普通用户只看得到自己的隧道，管理员可加备注。"},{"icon":"🔄","title":"面板内一键更新","details":"关于页检测更新 → 你手动确认 → 自动拉取代码并重启，登录状态保留。更新源失败会自动切换国内镜像。"},{"icon":"⚡","title":"国内网络加速","details":"拉代码、拉基础镜像、装 npm 依赖三个环节默认走国内可用源，不用改 daemon.json、不用配代理。"},{"icon":"🔌","title":"外部 API 与 MCP","details":"自带 RESTful API（19092）与 MCP 服务（19093），可让 AI 客户端直接查询和操控你的隧道。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790778157000}'),i={name:"index.md"};function l(r,a,d,o,p,h){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>原版「飞牛 Cloudflare Tunnel」面板同时只能保持 <strong>1 条</strong>隧道在线，想跑多个内网服务就得反复切换。本项目重构为<strong>单容器多隧道架构</strong>——每条隧道是独立子进程，互不影响，可以同时挂载多个内网服务。</p><h2 id="三分钟跑起来" tabindex="-1">三分钟跑起来 <a class="header-anchor" href="#三分钟跑起来" aria-label="Permalink to &quot;三分钟跑起来&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 下载（国内直连不稳就用第二行）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/lieren2012/cloudflare-tunnel-manager.git</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git clone https://v4.gh-proxy.org/https://github.com/lieren2012/cloudflare-tunnel-manager.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 构建并启动</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflare-tunnel-manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>然后浏览器打开 <code>http://你的NAS地址:19090</code>，按引导注册管理员账户。</p><p>接下来的路：<strong><a href="/cloudflare-tunnel-manager/get-credentials">获取 Cloudflare 凭据</a></strong> → <strong><a href="/cloudflare-tunnel-manager/guide/">填进面板并接入第一条隧道</a></strong></p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>系统</td><td>Linux / NAS（飞牛、群晖等），支持 Docker</td></tr><tr><td>Docker</td><td>支持 <code>docker compose</code> 或 <code>docker-compose</code></td></tr><tr><td>网络</td><td>能访问 Cloudflare 边缘（国内正常网络即可）</td></tr><tr><td>前置</td><td>一个已托管到 Cloudflare 的域名（免费套餐就行）</td></tr></tbody></table>`,8)])])}const k=e(i,[["render",l]]);export{u as __pageData,k as default};
